public class Student {
    private String name;
    private int age;

    public void setAge(int age) {
        if (age < 0 || age > 150) {
            throw new IllegalArgumentException("年龄不合法");
        }
        this.age = age;
    }

    public int getAge() {
        return age;
    }
}

public class Animal {
    protected String name;

    public void eat() {
        System.out.println(name + " 在吃东西");
    }
}

public class Dog extends Animal {
    public void bark() {
        System.out.println(name + " 在叫");   // 直接用父类的 name
    }
}

public class Dog extends Animal {
    @Override
    public void eat() {
        System.out.println(name + " 在啃骨头");
    }
}

Animal a = new Dog();
a.eat();     // 输出「在啃骨头」，调用的是 Dog 重写后的方法

public void feedAll(List<Animal> animals) {
    for (Animal a : animals) {
        a.eat();     // 各自执行自己的实现
    }
}

